// Synthetic receipt generated by the actual local PostgreSQL migration38 reserve
// and Python receipt_facts projection on2026-10-14. No real customer or provider.
import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {checkedReceiptFacts} from '../browser/booking/protocol.mjs';
import {createBookingDetails} from '../browser/booking/booking-details.mjs';
const facts=JSON.parse(await readFile(new URL('./fixtures/clinic-sql-public-facts.json',import.meta.url),'utf8'));
test('actual SQL and Python clinic facts cross browser validation and read-only lookup with null hold',async()=>{
 assert.equal(checkedReceiptFacts(facts,facts.request_id),facts);assert.equal(facts.hold_expires_at,null);assert.equal(facts.amount_due_paise,facts.amount_paise);
 const summary=Object.fromEntries(['request_id','booking_revision','service_name','starts_at','ends_at','timezone','appointment_state','facts_version','resource_id','resource_name','display_duration'].map(k=>[k,facts[k]]));
 let calls=0;const controller=createBookingDetails({product:{getSnapshot:()=>({enabled:true,verified:true,checking:false,activation_epoch:'11111111-1111-4111-8111-111111111111'}),subscribe:()=>()=>{}},fetcher:async()=>new Response(JSON.stringify(++calls===1?{version:1,kind:'list',server_now:facts.server_now,items:[summary],next_cursor:null}:{version:1,kind:'detail',receipt:facts,capabilities:{refresh:true,download_pdf:true}}),{headers:{'content-type':'application/json'}})});
 const stop=controller.start(null);try{controller.edit('full_name','Synthetic Customer');controller.edit('phone','9876543210');await controller.search();assert.equal(controller.getSnapshot().error,'');assert.deepEqual(controller.getSnapshot().receipt,facts);}finally{stop();}
});
